// CRT test pattern — SMPTE-style color bars, scanlines, subtle vignette.
// Helper functions are compiled at mediump; main() restores highp.
uniform float uBrightness;   // @param 1.0 0 2
uniform float uScanline;     // @param 0.35 0 1
uniform float uScanPixels;   // @param 3.0 1 8
uniform float uVignette;     // @param 0.3 0 1
uniform float uFlicker;      // @param 0.025 0 0.2
uniform float uRoll;         // @param 0.06 0 0.3
uniform float uRollSpeed;    // @param 0.12 0 1

precision mediump float;

// Top band: seven 75% bars
vec3 topBar(float x) {
  float i = clamp(floor(x * 7.0), 0.0, 6.0);
  if (i < 0.5) return vec3(0.75, 0.75, 0.75);
  if (i < 1.5) return vec3(0.75, 0.75, 0.0);
  if (i < 2.5) return vec3(0.0, 0.75, 0.75);
  if (i < 3.5) return vec3(0.0, 0.75, 0.0);
  if (i < 4.5) return vec3(0.75, 0.0, 0.75);
  if (i < 5.5) return vec3(0.75, 0.0, 0.0);
  return vec3(0.0, 0.0, 0.75);
}

// Middle strip: reverse castellations
vec3 midBar(float x) {
  float i = clamp(floor(x * 7.0), 0.0, 6.0);
  if (i < 0.5) return vec3(0.0, 0.0, 0.75);
  if (i < 1.5) return vec3(0.075);
  if (i < 2.5) return vec3(0.75, 0.0, 0.75);
  if (i < 3.5) return vec3(0.075);
  if (i < 4.5) return vec3(0.0, 0.75, 0.75);
  if (i < 5.5) return vec3(0.075);
  return vec3(0.75, 0.75, 0.75);
}

// Bottom: -I, 100% white, +Q, black, PLUGE, black
vec3 lowBar(float x) {
  if (x < 5.0 / 28.0)  return vec3(0.0, 0.13, 0.30);
  if (x < 10.0 / 28.0) return vec3(1.0);
  if (x < 15.0 / 28.0) return vec3(0.20, 0.0, 0.42);
  if (x < 5.0 / 7.0)   return vec3(0.075);
  if (x < 6.0 / 7.0) {
    float k = floor((x - 5.0 / 7.0) * 21.0);
    return vec3(k < 0.5 ? 0.035 : (k < 1.5 ? 0.075 : 0.115));
  }
  return vec3(0.075);
}

vec3 testPattern(vec2 q) {
  // q.y measured from the top of the layer
  if (q.y < 0.67) return topBar(q.x);
  if (q.y < 0.75) return midBar(q.x);
  return lowBar(q.x);
}

// phase is fract(pixelY / linePitch), computed at highp by the caller
float scanlineMask(float phase, float amount) {
  float s = 0.5 + 0.5 * cos(6.28318 * phase);
  return 1.0 - amount * (1.0 - s * s);
}

float vignette(vec2 q, float amount) {
  vec2 d = q - 0.5;
  float r = dot(d, d) * 2.0;
  return 1.0 - amount * smoothstep(0.15, 1.0, r);
}

precision highp float;

void main() {
  vec2 q = vec2(uv.x, 1.0 - uv.y);
  vec3 col = testPattern(q) * uBrightness;

  // Scanlines locked to layer pixels
  float py = uv.y * iResolution.y;
  float phase = fract(py / max(uScanPixels, 1.0));
  col *= scanlineMask(phase, uScanline);

  // Faint rolling refresh band
  float roll = fract(q.y - iTime * uRollSpeed);
  col *= 1.0 + uRoll * smoothstep(0.92, 1.0, roll) * (1.0 - smoothstep(0.0, 0.02, 1.0 - roll) * 0.0);

  // Frame-rate flicker
  col *= 1.0 - uFlicker * hash1(floor(iTime * 30.0));

  col *= vignette(uv, uVignette);
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
